/// A newer build than the running one — see `UpdateCheckerService`.
class AppUpdateInfo {
  final String version;
  final int buildNumber;

  /// The APK to install (Android), or null on the web, where updating is
  /// just reloading the page.
  final String? downloadUrl;

  /// APK size in bytes, when GitHub reports it.
  final int? sizeBytes;

  /// "What's new" lines, generated by CI from the commits in this release.
  final List<String> notes;

  const AppUpdateInfo({
    required this.version,
    required this.buildNumber,
    this.downloadUrl,
    this.sizeBytes,
    this.notes = const [],
  });
}
